#include <Servo.h>

// Объявляем объекты для каждого сервопривода
Servo baseServo;      // основание (поворот вокруг оси)
Servo shoulderServo;  // плечо
Servo elbowServo;     // локоть
Servo gripperServo;   // захват (клешня)

// Пины, к которым подключены серво (подстройте под свою схему!)
const int pinBase = 9;
const int pinShoulder = 10;
const int pinElbow = 11;
const int pinGripper = 5;

void setup() {
  // Привязываем объекты к пинам
  baseServo.attach(pinBase);
  shoulderServo.attach(pinShoulder);
  elbowServo.attach(pinElbow);
  gripperServo.attach(pinGripper);

  // Начальная позиция — нейтраль 90 градусов
  baseServo.write(90);
  shoulderServo.write(90);
  elbowServo.write(90);
  gripperServo.write(90);

  delay(1500); // даём время встать в позицию
}

void loop() {
  // Пример простого алгоритма: «взять предмет»

  // 1. Поворот основания в сторону (условно «к предмету»)
  baseServo.write(45);
  delay(1000);

  // 2. Опускаем плечо и локоть, чтобы дотянуться
  shoulderServo.write(130);
  elbowServo.write(30);
  delay(1000);

  // 3. Открываем захват
  gripperServo.write(40);
  delay(500);

  // 4. Закрываем захват (захват предмета)
  gripperServo.write(80);
  delay(1000);

  // 5. Возвращаем плечо/локоть вверх
  shoulderServo.write(90);
  elbowServo.write(90);
  delay(1000);

  // 6. Возвращаем основание в центр
  baseServo.write(90);
  delay(1000);

  // 7. Открываем захват (освобождаем предмет)
  gripperServo.write(40);
  delay(1000);

  // Возвращаем всё в нейтраль
  baseServo.write(90);
  shoulderServo.write(90);
  elbowServo.write(90);
  gripperServo.write(90);

  delay(2000); // пауза перед повторением
}
